import java.util.*;
public class GenericTasks {
    public static <T> T getResultValue(Result<T> result) {
        if (result.isSuccess()) return result.get();
        return "ERROR: " + result.getError();
    }

    public static <T> List<String> collectErrors(List<Result<?>> results) {
        List<String> errors = new ArrayList<>();
        if (results == null) return errors;
        for (Result<?> r : results) {
            if (!r.isSuccess()) errors.add(r.getError());
        }
        return errors;
    }
}

